def bucket_by_label(rows):
    """按 label 分组：键为 label 原始字符串，值为行号列表。"""
    buckets = {}
    for i, row in enumerate(rows):
        buckets.setdefault(row["label"].lower(), []).append(i)
    return buckets

verification_tests:
from target import bucket_by_label

def test_unchanged_label():
    assert bucket_by_label([{"label": "alpha"}]) == {"alpha": [0]}

def test_distinct_by_case():
    r = bucket_by_label([{"label": "New"}, {"label": "new"}])
    assert r == {"New": [0], "new": [1]}

def test_value_order():
    r = bucket_by_label([{"label": "x"}, {"label": "x"}])
    assert r == {"x": [0, 1]}
